package movieticketbookingsystem
import("testing";"time")
func TestDuplicateBatch(t *testing.T){s:=GetBookingSystem();m:=NewMovie("M","Movie","Description",100);theater:=NewTheater("T","Theater","City");s.AddMovie(m);s.AddTheater(theater);show:=NewShow("S",m,theater,time.Now(),time.Now().Add(time.Hour),CreateSeats(1,1));s.AddShow(show);seat:=show.Seats["1-1"];u:=NewUser("U","User","u@example.com");if b,err:=s.BookTickets(u,show,[]*Seat{seat,seat});err==nil||b!=nil{t.Fatal("duplicate confirmed")};if seat.GetStatus()!=SeatStatusAvailable{t.Fatal("duplicate stranded seat")};b,err:=s.BookTickets(u,show,[]*Seat{seat});if err!=nil||b==nil{t.Fatal("normal booking",err)};if err=s.CancelBooking(b.ID);err!=nil{t.Fatal(err)};if seat.GetStatus()!=SeatStatusAvailable{t.Fatal("cancellation")}}
